#include <iostream>
#include <vector>

using namespace std;

int n, q;
vector<int> bit;
vector<int> a;

void update(int idx, int delta) {
    for (; idx <= n; idx += idx & -idx) {
        bit[idx] += delta;
    }
}

int query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n >> q)) return 0;

    bit.assign(n + 1, 0);
    a.assign(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        update(i, a[i]);
    }

    for (int i = 0; i < q; ++i) {
        int type;
        cin >> type;
        if (type == 0) {
            int k, p;
            cin >> k >> p;
            int delta = p - a[k];
            a[k] = p;
            update(k, delta);
        } else if (type == 1) {
            int k;
            cin >> k;
            cout << query(k) << "\n";
        }
    }

    return 0;
}
